using Astrea.BattleActions;
using LittleLeo;
using UnityEngine;
using UnityEngine.Localization.SmartFormat;

namespace Astrea;

[CreateAssetMenu(fileName = "OnDiceRerollEffect", menuName = "Data/Battle/Effects/Enemy/OnDiceReroll Effect")]
public class OnDiceRerollEffect : Effect
{
	[SerializeField]
	private BattleAction battleAction;

	[SerializeField]
	private int actionValue = 1;

	[SerializeField]
	private OmenLogic omenLogic;

	[SerializeField]
	private float vfxDelay;

	[SerializeField]
	private bool useAmountOnDescription;

	[SerializeField]
	private bool rollingStars;

	public override string GetEffectDescription(int amount, GameObject effectOwner = null)
	{
		return Smart.Format(GetLocalizedDescription(), battleAction.GetActionDescription(useAmountOnDescription ? amount : actionValue).LowercaseFirst().RemoveLast());
	}

	public void ActivateAction(GameObject effectOwner, int diceRerolledAmount, int effectAmount)
	{
		effectOwner.GetComponent<UnitEffects>().IsEffectActive(this);
		SpawnVFX(4f);
		if (IsVFXEnabled())
		{
			PlayEffectActivationSFX();
			InvokeAlternatives.Invoke(ReferenceSingleton<CoroutineHandler>.Instance, vfxDelay, delegate
			{
				omenLogic.ActivateOmen(battleAction, diceRerolledAmount * actionValue * effectAmount, null, null);
			});
		}
		else
		{
			omenLogic.ActivateOmen(battleAction, diceRerolledAmount * actionValue * effectAmount, null, null);
		}
	}
}
